import { getUsers } from '@/actions/admin/get-users'
import { UsersPageClient } from '@/components/admin/UsersPageClient'

// Force dynamic rendering since we use auth()
export const dynamic = 'force-dynamic'

export default async function AdminUsers() {
    // Fetch users from Clerk
    let clerkUsers = []
    try {
        const fetchedUsers = await getUsers(100) // Fetch up to 100 users
        
        // Map Clerk User objects to ClerkUser type expected by components
        clerkUsers = fetchedUsers.map((user) => ({
            id: user.id,
            firstName: user.firstName || null,
            lastName: user.lastName || null,
            username: user.username || null,
            imageUrl: user.imageUrl || '',
            emailAddresses: user.emailAddresses || [],
            publicMetadata: user.publicMetadata || {},
            // Convert Date to timestamp (number) if needed
            createdAt: user.createdAt ? (typeof user.createdAt === 'number' ? user.createdAt : new Date(user.createdAt).getTime()) : Date.now(),
            lastActiveAt: user.lastActiveAt ? (typeof user.lastActiveAt === 'number' ? user.lastActiveAt : new Date(user.lastActiveAt).getTime()) : null,
        }))
    } catch (error) {
        console.error('Failed to fetch users:', error)
        // Continue with empty array if fetch fails
    }

    return (
        <div className="space-y-6 animate-fadeIn">
            {/* Header */}
            <header>
                <p className="text-[10px] text-accent uppercase font-bold tracking-[0.3em] mb-1">
                    Entity Management
                </p>
                <h1 className="text-4xl font-extrabold tracking-tight mb-2">
                    Quản Lý Đệ Tử
                </h1>
                <p className="text-sm text-muted-foreground">
                    Total Users: <span className="font-semibold text-foreground">{clerkUsers.length}</span>
                </p>
            </header>

            {/* Toolbar and Users Table with Client-side Search */}
            <div className="gap-6">
                <UsersPageClient initialUsers={clerkUsers} />
            </div>
        </div>
    )
}
